 "client_cluster_around_title": [
  "locale:116480 [quest_dialog | Stillwater Crossing | Chef: Stillwater Inn] \"It's a good thing you showed up when you did! Gavin has been gone for much too long and orders are really starting to stack up!<BR><BR>I'll teach you how to coo\"",
  "locale:116483 [quest_dialog | Stillwater Crossing | Chef: Stillwater Inn] \"Those steaks look tasty! You've got talent as a chef!<BR><BR>You need to find ingredients if you want to make more. Find them by harvesting at farm fields, and \"",
  "locale:116484 [quest_objective | Stillwater Crossing | Brawler: Graveyard Grumble] \"Hey, want to <font color = '#D9781A'>fight a wraith</font> for me? It's in the <font color = '#D9781A'>graveyard</font> behind me. It's really creepy, so please\"",
  "locale:116485 [quest_title | Stillwater Crossing | Brawler: Graveyard Grumble] 'Brawler: Graveyard Grumble'",
  "locale:116486 [quest_objective | - | Caitlyn Gravefog] 'Caitlyn Gravefog needs help removing a troublesome wraith from her graveyard. Enter the Cursed Graveyard north west of Stillwater Crossing and defeat the wraith'",
