 ],
 "client_cluster_around_title": [
  "locale:438814 [item | Rumbledome | Rumbledome Spike Trap] 'Rumbledome Spike Trap'",
  "locale:438816 [quest_objective | Rumbledome | Rumbledome] 'Defeat the second wave of Rumbledome Gladiators!'",
  "locale:438817 [quest_objective | Rumbledome | Rumbledome | FLAG duplicate: near-identical to 438816] 'Defeat the second batch of the formidable Rumbledome Gladiators'",
  "locale:438818 [quest_dialog | Rumbledome | Rumbledome] 'Welcome one and all - to the RUMBLEDOME!'",
  "locale:438819 [quest_dialog | Rumbledome | Rumbledome] \"Our first contender: Stumbling all the way down the road from Wheelie Pete's - BRONZEKNUCKLES!\"",
  "locale:438820 [quest_dialog | Rumbledome | Rumbledome] \"What a great warm-up! Speaking of warm-ups - it's time for our FLAME TRAPS!\"",
  "locale:438821 [quest_dialog | Rumbledome | Rumbledome] 'Our next challenger spent years sparring with the manguana hunters in the Sandscale Oasis. He is - SILVERFIST!'",
  "locale:438822 [quest_dialog | Rumbledome | Rumbledome] \"Such a shocking turn of events! Shocking? Yes, it's time for the SHOCK TRAPS!\"",
  "locale:438823 [quest_dialog | Rumbledome | Rumbledome] 'Our next combatant needs no introduction. Some say he was born in the Rumbledome itself.'",
  "locale:438824 [quest_dialog | Rumbledome | Rumbledome] 'The champion of the Rumbledome - GOLDCRUSHER!'",
  "locale:438825 [quest_dialog | Rumbledome | Rumbledome | FLAG duplicate: near-identical to 438824] \"The Rumbledome's former champion - GOLDCRUSHER!\"",
  "locale:438826 [quest_dialog | Rumbledome | Rumbledome] 'What an amazing turn of events! We have a NEW CHAMPION!'",
  "locale:438827 [quest_dialog | Rumbledome | Rumbledome] 'And the former champion goes down again! What an amazing fight!'",
  "locale:438828 [quest_dialog | Rumbledome | Rumbledome] \"Be sure to come back next time, because you never know what you'll see at - THE RUMBLEDOME!\"",
  "locale:438829 [npc_name | Rumbledome | Red Stonehammer] 'Red Stonehammer'",
  "locale:438830 [ui | - | Time Left: %1 Days | FLAG placeholder: unfilled format string] 'Time Left: %1 Days'",
  "locale:438831 [ui | - | Time Left: %1 Day | FLAG placeholder: unfilled format string] 'Time Left: %1 Day'",
  "locale:438832 [ui | - | Time Left timer] 'Time Left: %1 Hours'",
  "locale:438833 [ui | - | Time Left timer] 'Time Left: %1 Hour'",
